private static boolean equals(final byte[] name, final char[] buf, final int offset, final int len) {
  if (name.length != len) {
    return false;
  }
  for (int i = 0, j = offset; i < len; ++i, ++j) {
    if ((char) (name[i] & 0xff) != buf[j]) {
      return false;
    }
  }
  return true;
}
